import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import "./PatientDashboard.css";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [myOP, setMyOP] = useState(null);

  const [form, setForm] = useState({
    patientName: "",
    department: "",
    date: ""
  });

  const [queueCount, setQueueCount] = useState(0);

  const [notice, setNotice] = useState("");

  useEffect(() => {

    const load = async () => {

      const res = await fetch("http://localhost:5000/api/queue/all");
      const data = await res.json();

      const mine = data.find(
        q => q.patientName === form.patientName
      );

      setMyOP(mine || null);

      const waiting = data.filter(q => q.status === "InQueue");

      setQueueCount(waiting.length);

      if (mine) {

        const pos = waiting.findIndex(q => q._id === mine._id);

        if (pos >= 0 && pos < 3) {
          setNotice("Your turn is near");
        } else {
          setNotice("");
        }

      } else {
        setNotice("");
      }

    };

    load();
    socket.on("queueUpdated", load);

    return () => socket.off("queueUpdated");

  }, [form.patientName]);



  const bookOP = async () => {

    const res = await fetch(
      "http://localhost:5000/api/queue/book",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form)
      }
    );

    const data = await res.json();
    setMyOP(data);

  };



  const joinQueue = async (id) => {

    await fetch(
      `http://localhost:5000/api/queue/join/${id}`,
      { method: "PUT" }
    );

  };



  return (

    <div className="page">

      <div className="left">

        <div className="brand">
          HealSync
        </div>

        <div className="tag">
          Smart Hospital Queue System
        </div>

        {notice && (
          <div className="notice">
            {notice}
          </div>
        )}

        {!myOP && (

          <div className="form">

            <input
              placeholder="Patient Name"
              value={form.patientName}
              onChange={(e) =>
                setForm({ ...form, patientName: e.target.value })
              }
            />

            <input
              placeholder="Department"
              value={form.department}
              onChange={(e) =>
                setForm({ ...form, department: e.target.value })
              }
            />

            <input
              type="date"
              value={form.date}
              onChange={(e) =>
                setForm({ ...form, date: e.target.value })
              }
            />

            <button onClick={bookOP}>
              Book OP
            </button>

          </div>

        )}

      </div>



      <div className="right">

        <div className="card">

          <h3>Total OP</h3>
          <h1>{myOP ? 1 : 0}</h1>

        </div>



        <div className="card">

          <h3>Waiting List</h3>
          <h1>{queueCount}</h1>

        </div>



        {myOP && (

          <div className="op">

            <div className="title">
              My OP Status
            </div>

            <div className="row">
              <span>Token</span>
              <b>{myOP.tokenNumber}</b>
            </div>

            <div className="row">
              <span>Department</span>
              <b>{myOP.department}</b>
            </div>

            <div className="row">
              <span>Status</span>
              <b>{myOP.status}</b>
            </div>

            {myOP.status === "Confirmed" && (
              <button onClick={() => joinQueue(myOP._id)}>
                Join Queue
              </button>
            )}

            {myOP.status === "InQueue" && (
              <div className="waitingBox">
                You are in queue
              </div>
            )}

          </div>

        )}

      </div>

    </div>

  );

}

export default PatientDashboard;
